import re

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections = {}
    default_dict = {}
    current_section = None
    current_key = None
    current_value = None
    previous_line_was_key = False
    lines = text.splitlines()

    def interpolate(text, current_section, default_dict, sections, path=None):
        if path is None:
            path = []
        match = re.search(r'\$\{([^}]*)\}', text)
        if not match:
            return text
        key_part = match.group(1)
        if ':' in key_part:
            ref_section, ref_key = key_part.split(':', 1)
        else:
            ref_section = current_section
            ref_key = key_part
        if (ref_section, ref_key) in path:
            raise ValueError(f"Cycle detected in interpolation: {ref_key} in {ref_section}")
        new_path = path + [(ref_section, ref_key)]
        if ref_section == 'DEFAULT':
            if ref_key in default_dict:
                replacement = default_dict[ref_key]
            else:
                raise KeyError(f"Key {ref_key} not found in DEFAULT section")
        else:
            if ref_section not in sections:
                raise KeyError(f"Section {ref_section} not found")
            if ref_key in sections[ref_section]:
                replacement = sections[ref_section][ref_key]
            else:
                if ref_key in default_dict:
                    replacement = default_dict[ref_key]
                else:
                    raise KeyError(f"Key {ref_key} not found in section {ref_section} or DEFAULT")
        new_text = text[:match.start()] + replacement + text[match.end():]
        return interpolate(new_text, current_section, default_dict, sections, new_path)

    for line in lines:
        stripped_line = line.strip()
        if not stripped_line or stripped_line.startswith(';') or stripped_line.startswith('#'):
            previous_line_was_key = False
            continue
        section_match = re.match(r'^\s*\[([^\]]+)\]\s*$', line)
        if section_match:
            section_name = section_match.group(1).strip()
            if section_name == 'DEFAULT':
                current_section = 'DEFAULT'
                current_key = None
                current_value = None
            else:
                current_section = section_name
                if current_section not in sections:
                    sections[current_section] = {}
                current_key = None
                current_value = None
            previous_line_was_key = False
            continue
        if line.lstrip() != line:
            if current_key is not None:
                current_value += '\n' + line.strip()
                previous_line_was_key = False
                continue
            else:
                raise ValueError("Continuation line without previous key")
        if current_key is not None:
            if current_section == 'DEFAULT':
                default_dict[current_key] = current_value
            else:
                sections[current_section][current_key] = current_value
            current_key = None
            current_value = None
        main_part = line
        comment_pos = -1
        for i in range(len(main_part)):
            if i + 1 < len(main_part) and main_part[i] == ' ' and main_part[i+1] in (';', '#'):
                comment_pos = i
                break
        if comment_pos != -1:
            main_part = main_part[:comment_pos]
        split_pos = None
        for i, c in enumerate(main_part):
            if c in ('=', ':'):
                split_pos = i
                break
        if split_pos is None:
            raise ValueError("Invalid key line")
        key_str = main_part[:split_pos].strip().lower()
        value_str = main_part[split_pos+1:].strip()
        if value_str.startswith('"') and value_str.endswith('"'):
            value = value_str[1:-1]
        else:
            value = value_str
        try:
            interpolated_value = interpolate(value, current_section, default_dict, sections)
        except KeyError as e:
            raise e
        except ValueError as e:
            raise e
        current_key = key_str
        current_value = interpolated_value
        previous_line_was_key = True

    if current_key is not None:
        if current_section == 'DEFAULT':
            default_dict[current_key] = current_value
        else:
            sections[current_section][current_key] = current_value

    result = {}
    for section in sections:
        merged = {}
        merged.update(default_dict)
        merged.update(sections[section])
        result[section] = merged

    return result
