def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    customer_data = {}
    for row in rows:
        customer = row.get('customer', '').strip()
        if not customer:
            continue
        amount_str = row.get('amount', '')
        try:
            cleaned = amount_str.replace('$', '').replace(',', '')
            amount = float(cleaned)
        except ValueError:
            continue
        lower_customer = customer.lower()
        if lower_customer not in customer_data:
            customer_data[lower_customer] = (customer, amount)
        else:
            existing_customer, total = customer_data[lower_customer]
            customer_data[lower_customer] = (existing_customer, total + amount)
    result = []
    for key in customer_data:
        original_name, total = customer_data[key]
        rounded_total = round(total, 2)
        result.append((original_name, rounded_total))
    result.sort(key=lambda x: (-x[1], x[0]))
    return result[:n]
